import{_ as d,o as a,c as e,a6 as r}from"./chunks/framework.QQy01QNh.js";const b=JSON.parse('{"title":"第十二部分　条件前瞻与有限选择","description":"","frontmatter":{"title":"第十二部分　条件前瞻与有限选择"},"headers":[],"relativePath":"theory/part-12.md","filePath":"theory/part-12.md"}'),o={name:"theory/part-12.md"};function h(i,t,n,p,s,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<div class="theory-source"><p><a id="part_12"></a></p><h1 id="part-title-12" tabindex="-1">第十二部分　条件前瞻与有限选择 <a class="header-anchor" href="#part-title-12" aria-label="Permalink to &quot;第十二部分　条件前瞻与有限选择 {#part-title-12}&quot;">​</a></h1><p>推演把条件和路径展开，条件前瞻进一步承担可失败的未来判断，有限选择则在价值、保护和授权边界内比较可做、如何做、何时停以及何时不做。本部分把二者放在相邻位置，是为了形成工作闭环；把二者分成不同合同，是为了防止“预测了某个后果”被偷换成“因此有权让别人承担某项行动”。比较和推荐方案属于分析交付，可以在规范前提与限制明确时完成；现实采用与执行则须另行通过适用的保护、复核和授权。</p><h2 id="section-12-1" tabindex="-1">12.1　四类输出的隔离 <a class="header-anchor" href="#section-12-1" aria-label="Permalink to &quot;12.1　四类输出的隔离 {#section-12-1}&quot;">​</a></h2><p>解释、推演、条件前瞻和有限选择必须分别标记。</p><table tabindex="0"><thead><tr><th>输出</th><th>核心问题</th><th>必需输入</th><th>输出上限</th></tr></thead><tbody><tr><td>解释</td><td>已发生什么，可能为何发生</td><td>对象、尺度、证据、机制、反例</td><td>有边界的机制说明</td></tr><tr><td>推演</td><td>条件或事件后可能沿哪些路径演化</td><td>冻结快照、更新规则、时钟、分叉</td><td>条件路径和区分信号</td></tr><tr><td>条件前瞻</td><td>在目标与期限内哪条路径更值得期待</td><td>结果前登记、简单基线、指标、回写</td><td>可校准、可失败的判断</td></tr><tr><td>有限选择</td><td>在明示规范前提下比较与推荐方案；现实采用另经保护、复核和授权</td><td>分析需规范前提、证据、方案、代价与受影响者；现实采用另需 N、PF、J、O、C12</td><td>可反驳的分析推荐或经授权的有限选择记录；两者身份分开</td></tr></tbody></table><p>解释可以生成推演候选，却不能自动证明未来；推演可以生成前瞻候选，却不能把所有路径都算成功；前瞻可以进入方案比较，却不能自动生成价值或权限；有限选择即使通过，也不保证现实执行会成功，仍需停止、回滚与结果回写。</p><h2 id="section-12-2" tabindex="-1">12.2　条件前瞻登记 <a class="header-anchor" href="#section-12-2" aria-label="Permalink to &quot;12.2　条件前瞻登记 {#section-12-2}&quot;">​</a></h2><p>每条前瞻在输入截止后、结果出现前冻结。最低字段包括：前瞻 ID、模型版本、目标、期限、对象与圈层范围、基线时点、输入截止、简单基线、候选机制、路径集合、概率或排序表达、校准计划、决策阈值（用于相应决策时；否则标为不适用）、早期信号、反向信号、暂停条件、退役条件、结果回写、登记时间和证据引用。</p><p>目标必须可判定。例如“关系会变好”需要改写为指定时间窗内哪些可观察量改变、由谁观察、达到什么阈值以及何种结果视为未决。期限可以是窗口，不必伪造精确日期。对象和圈层范围必须冻结，避免结果后缩小到成功子群。</p><table tabindex="0"><thead><tr><th>登记项</th><th>最低问题</th><th>防止的偏差</th></tr></thead><tbody><tr><td>目标</td><td>到期时如何知道发生、未发生或无法判断</td><td>模糊成功</td></tr><tr><td>期限</td><td>从何时到何时，何时停止收集输入</td><td>无限等待</td></tr><tr><td>简单基线</td><td>不用多圈层机制时的比较预测是什么</td><td>复杂故事自我胜利</td></tr><tr><td>路径</td><td>哪些路径互斥、并行或不可比较</td><td>事后挑选</td></tr><tr><td>表达</td><td>概率、区间、等级还是仅方向</td><td>伪精确</td></tr><tr><td>信号</td><td>什么提高或降低路径支持</td><td>只找支持证据</td></tr><tr><td>回写</td><td>结果由何来源、何时追加</td><td>失败消失</td></tr></tbody></table><h3 id="section-12-2-1" tabindex="-1">12.2.1　局部可预测性边界 <a class="header-anchor" href="#section-12-2-1" aria-label="Permalink to &quot;12.2.1　局部可预测性边界 {#section-12-2-1}&quot;">​</a></h3><p>任何可预测性主张都必须绑定对象、状态区域、尺度与圈层、时间窗、允许误差、可用信息、计算和观测资源、模型版本、基线、弃权与失效条件。世界整体是否可预测不是本框架能够直接回答的问题；只能检验某项任务在明确边界内是否获得有限增量。</p><p>分类、等级、区间和概率分别承担不同的测量与表达责任，不是一条每项任务都必须依次爬升的精度阶梯。采用哪一种表达，须由目标、单位、生成方法、识别条件和校准状态支持；定性方向没有依据时也应保留未知，不能把它当作概率缺失后的默认答案。形式模型中的已知概率和经验概率分别说明假设与外推边界，不由文字结构或人工智能补造现实参数。引用现有数学或物理理论时，必须一并登记原对象、假设、极限或尺度律、误差、有效域、对象映射、反例和退出条件，不能只借公式外形。</p><h3 id="section-12-2-2" tabindex="-1">12.2.2　递归前瞻的按阶评价 <a class="header-anchor" href="#section-12-2-2" aria-label="Permalink to &quot;12.2.2　递归前瞻的按阶评价 {#section-12-2-2}&quot;">​</a></h3><p>第一、第二、第三阶分别冻结并分别评价，不能合成一个总命中率。每一阶都要与不继续递归的状态延续、直接远期判断和更浅阶次加简单延续比较。若三阶只增加故事而没有稳定样本外增益，它可以保留为探索情景，但不得取得前瞻能力资格。</p><p>没有新外部材料进入时，全部子运行的来源谱系仍终止于同一冻结起点。后处理可以增加模型内部的推理内容、暴露敏感性和隐藏后果，却不能自造现实证据。真实中间结果到达后，应建立新的冻结运行，与原递归路径比较，不能把结果倒灌进旧路径。</p><h2 id="section-12-3" tabindex="-1">12.3　简单基线与增量能力 <a class="header-anchor" href="#section-12-3" aria-label="Permalink to &quot;12.3　简单基线与增量能力 {#section-12-3}&quot;">​</a></h2><p>多圈层模型若声称增加前瞻能力，须与任务适配的简单模型和领域已有方法作同信息、同截止、同目标与同评价规则的比较。比较材料、推理预算和调参机会尽量相称，并分别说明增加信息、增加计算和增加结构假设的贡献；不要求把简单基线人为堆成与复杂模型相同规模。预测系统通常需要独立测试或样本外复核，无法获得时明确保留能力未证实状态。</p><p>常用基线包括：延续当前趋势；沿用最近状态；历史频率；只使用行动者状态；只使用主圈层状态；领域已有模型。比较应使用相同目标、期限、数据截止和评价指标。若复杂模型改善解释但不改善预测，应如实登记“解释增益存在、前瞻增益未获支持”。</p><p>模型复杂度也有成本：更多变量增加缺失、测量误差、隐私风险、过拟合和维护债。若多圈层模型只在少量案例中有效，应限定适用域；若增益随时间消失，应降级或退役；若简单基线表现相同，应优先简单模型。</p><h2 id="section-12-4" tabindex="-1">12.4　概率、等级与时间窗 <a class="header-anchor" href="#section-12-4" aria-label="Permalink to &quot;12.4　概率、等级与时间窗 {#section-12-4}&quot;">​</a></h2><p>证据允许时，可以给出概率或概率区间，并说明模型、先验、数据和校准依据；缺少概率依据时，可在有证据支持的范围内给出等级或路径比较。样本数量不单独决定输出类型；连方向或排序也不可识别时，应明确保持未知，给出有判别力的观察点，而不把“只说方向”当作免除证据责任。表达强度由具体证据和用途决定，不由使用者希望的确定性决定。</p><table tabindex="0"><thead><tr><th>证据状态</th><th>合适表达</th><th>必须同时给出</th></tr></thead><tbody><tr><td>有明确依据的概率模型或经验估计，目标可判定</td><td>概率或概率区间</td><td>生成方法、先验（如适用）、数据、适用边界与校准状态</td></tr><tr><td>概率依据不足，但路径等级或排序有依据</td><td>支持等级或排序</td><td>依据、不可比较项和反向信号</td></tr><tr><td>方向有识别依据；否则方向仍未知</td><td>有依据的条件方向，或明确保持未知</td><td>识别条件、触发点、最小观察和停止条件</td></tr><tr><td>目标或对象不稳定</td><td>不发布前瞻</td><td>需要重新定义的合同</td></tr></tbody></table><p>时间窗应与机制时钟相符。即时反应可以使用短窗，组织或制度变化需要更长窗。把长期机制压缩到短期，会误判无效；把短期信号无限外推，会误判趋势。多个时钟并存时，可以为不同中间结果分别登记期限。</p><p>现实概率、行动者的主观信念、决策中的权重、模型的路径排序以及下一步计算分配，是不同的量。现实概率须说明目标事件与估计或校准依据；主观信念说明谁在什么信息下如何判断；决策权重依所采用的描述模型或价值前提解释；计算优先级说明为什么值得继续研究。不能把模型多抽样得到的分支频率直接当现实概率，也不能把最值得检查或最希望发生的路径写成最可能发生。</p><p>在概率无法可靠确定时，可以因后果严重、应对窗口短或容易区分而优先检查一条路径。此时公开优先级的理由与预算，保留概率未知；不能为排序需要编造百分比。行动比较仍须另外说明规范目标、分配后果及可执行选择，不从概率排序直接推出推荐排序。</p><p>概率与等级使用不同语义：模型在给定假设下的条件概率、个人判断的不确定性、长期重复任务中的经验校准，以及规范上的优先等级，不得共用一个数字冒充同一对象。后验可由小样本与明确先验产生，但其现实适用仍依模型；样本很大也不能修复错误的观测口径。没有依据时，方向也可能未知，而不是降为“只判断方向”就自动可靠。〔研究03.04、07.07〕</p><h2 id="section-12-5" tabindex="-1">12.5　校准与评价 <a class="header-anchor" href="#section-12-5" aria-label="Permalink to &quot;12.5　校准与评价 {#section-12-5}&quot;">​</a></h2><p>前瞻能力不是文风上的“说得准”，而是长期登记的结果。概率任务适用时使用 Brier 分数、对数损失、校准曲线、分辨率和区间覆盖率；排序任务使用预登记的排序指标；事件检测使用精确率、召回率或领域指标；时间预测使用窗口覆盖和提前量。</p><p>任何指标都要与实际用途匹配。若低概率高损害事件需要谨慎，评价不能只看总体准确率；若输出只用于提醒观察，假阳性成本与用于强制行动不同。指标表现良好也不证明模型解释正确，更不证明行动正当。</p><p>预警投入使用后，评价对象须说明响应制度：是在既定制度下预测实际事件，还是另问发布或行动改变了什么。保留会影响评价的触达、执行、对象进入退出及资料形成记录；制度变化时重新说明哪些结果仍可比较。没有观察到事件，既不能自动记为误报，也不能据此认定保护成功。关于避免损害的主张另须相称的因果比较；对已定义在现行响应制度下的预测，仍可按原目标评价，不必将所有预测任务改为干预效果研究。原目标、期限与成功规则不得因响应发生而事后改写。（Perdomo等，2020；另见§2.4与§12.6）</p><table tabindex="0"><thead><tr><th>评价维度</th><th>说明</th><th>失败后的动作</th></tr></thead><tbody><tr><td>校准</td><td>说 70% 的事件长期是否约 70% 发生</td><td>调整表达或降级概率输出</td></tr><tr><td>分辨率</td><td>模型能否区分不同风险或路径</td><td>删除无贡献变量、退回基线</td></tr><tr><td>覆盖率</td><td>区间或时间窗是否覆盖实际结果</td><td>扩大区间或修正时钟</td></tr><tr><td>基线增益</td><td>是否优于简单模型</td><td>停止复杂模型的前瞻声明</td></tr><tr><td>稳定性</td><td>跨时间、地点和边界是否保持</td><td>限定适用域或退役</td></tr><tr><td>分配误差</td><td>哪些位置持续被低估或误报</td><td>受影响者复核、补救和保护升级</td></tr></tbody></table><p>评价入口可用三个并行问题固定判断：</p><table tabindex="0"><thead><tr><th>所问问题</th><th>当前材料足够时可以回答什么</th><th>需要保留什么</th></tr></thead><tbody><tr><td>原预测对冻结目标表现怎样</td><td>依同口径真实标签计算损失、分类结果或覆盖</td><td>单案得分不等长期校准；缺失标签不填零</td></tr><tr><td>发布或行动改变了多少结果</td><td>依相称因果比较给出限定效果</td><td>观察到无事件不能单独区分原本低风险与成功避免</td></tr><tr><td>采用这套预测及响应是否合宜</td><td>在明示规范前提下比较保护、误拒、时延、分配和成本</td><td>预测准确或某项效果为正都不单独产生权限</td></tr></tbody></table><p>例如，预先登记在现行响应制度下某事件概率为 0.8，到期完整标签为 0，则逐案 Brier 损失为 0.64；若二元分类阈值事先定为 0.5，也可以登记该目标下的假阳性。这个有限计算不说明无行动时的风险，更不说明响应无效。若监测离线而未取得标签，便不能使用同一计算。已批准或已接受服务者的完整标签，也只能直接评价相应人群；扩展到被拒、未到达或退出者时，需要其标签或有根据的识别与界定方法。</p><p>响应制度改变后，先判断原目标是否仍是同一个问题。若保持原目标，就如实报告性能变化；若改成另一响应制度或另一人群的目标，建立新的登记并保留旧结果。不能因为存在反身性，就取消本来可以计算的评分，也不能以一次成功响应事后救援所有错误预测。</p><h2 id="section-12-6" tabindex="-1">12.6　早期信号、反向信号与触发点 <a class="header-anchor" href="#section-12-6" aria-label="Permalink to &quot;12.6　早期信号、反向信号与触发点 {#section-12-6}&quot;">​</a></h2><p>早期信号不是结果的缩小版，而是路径机制应当先产生的可观察变化。反向信号表示该路径的关键条件正在失效或竞争路径得到支持。两者必须在结果前登记，避免只收集支持材料。</p><p>触发点把前瞻连接到复核：观察到信号后，不是自动行动，而是重新评估对象、路径、概率、规范和授权。高风险情形还应设置否决触发点，例如保护底板被突破、关键受影响者无法退出、数据来源失真或模型校准恶化。</p><p>时钟比较以可完成的行动为终点：发现信号、核验、发布、触达、理解、筹集资源、转移或起效，各有时延。算法提前发现并不保证最后一位受影响者能在伤害前获得保护。警报后没有出现损害时，按已冻结目标与标签条件判断能否登记业务假阳性；是否因应对成功而避免损害另行识别。业务假阳性率、警报中的虚警比例和漏报率分别保留分母。〔研究31.05〕</p><h2 id="section-12-7" tabindex="-1">12.7　前瞻的失败语义 <a class="header-anchor" href="#section-12-7" aria-label="Permalink to &quot;12.7　前瞻的失败语义 {#section-12-7}&quot;">​</a></h2><p>到期后结果可以是支持、未支持、未决、目标失效或无法评价。未决不是成功与失败的折中，而是合同规定的证据不足状态；无法评价必须说明数据、对象、期限或执行出了什么问题。目标失效表示预测对象或同一性判据已转换，不能把它计为命中。</p><p>结果后改目标、改期限、改圈层范围或把多个路径合并成“某种程度发生”，都不能保留原前瞻的成功资格。新解释可以建立新版本，但旧记录继续存在。</p><h2 id="section-12-8" tabindex="-1">12.8　从前瞻到有限选择的桥 <a class="header-anchor" href="#section-12-8" aria-label="Permalink to &quot;12.8　从前瞻到有限选择的桥 {#section-12-8}&quot;">​</a></h2><p>前瞻输出只回答条件后果。形成分析推荐前须明示规范前提、证据、受影响位置、方案、成本收益和改判条件；推荐不产生执行权限。进入现实采用前，必须补入：明示规范前提、选择主体、管辖权、受影响位置、权利底线、方案、成本与收益分布、授权、停止、申诉、回滚和补救。这里继续调用 N、PF、J、O 与 C12，不建立预测捷径。</p><p>预测不能自动生成授权。即使某条路径概率极高，也不说明任何人有权强迫他人承担避免该路径的成本；即使某行动平均收益最大，也不说明少数位置的权利可以被忽略；即使模型推荐不行动，也要审查不行动造成的持续伤害和责任。</p><h2 id="section-12-9" tabindex="-1">12.9　方案集必须包含行动与不行动 <a class="header-anchor" href="#section-12-9" aria-label="Permalink to &quot;12.9　方案集必须包含行动与不行动 {#section-12-9}&quot;">​</a></h2><p>方案生成逐项检查维持现状、主动行动、延迟行动、试探性小步行动、退出或转移，以及明确的不行动六种类别的适用性。适用类别形成真实、可比较的方案；不适用类别说明理由，不能为满足数量虚构方案。请求选择时不得删除明确的不行动基线，也不能把维持现状和不行动混为一项：维持现状可能需要持续资源和执行，不行动可能让现状自然变化。具体任务可以增加方案；未请求选择的任务不强制生成行动清单。</p><table tabindex="0"><thead><tr><th>方案类型</th><th>主要用途</th><th>必须检查的风险</th></tr></thead><tbody><tr><td>维持现状</td><td>保护已有稳定与承接</td><td>隐性成本、持续伤害、锁定</td></tr><tr><td>主动行动</td><td>快速改变路径或条件</td><td>权限、不可逆、跨圈层溢出</td></tr><tr><td>延迟行动</td><td>等待信息、程序或时机</td><td>延迟本身的损害和机会损失</td></tr><tr><td>试探行动</td><td>以可逆小步获取信息</td><td>试验成本由谁承担、能否真正回滚</td></tr><tr><td>退出或转移</td><td>结束不合适的对象或关系</td><td>无法退出者、责任与历史保存</td></tr><tr><td>不行动</td><td>避免越权或高风险动作</td><td>默认偏向、持续后果和不作为责任</td></tr></tbody></table><p>“不行动”不是不发生任何事。其他行动者、圈层、资源和时钟仍在变化。不行动方案要有基线时点、预期路径、观察计划、重新开启条件和责任主体。</p><h2 id="section-12-10" tabindex="-1">12.10　统一方案比较卡 <a class="header-anchor" href="#section-12-10" aria-label="Permalink to &quot;12.10　统一方案比较卡 {#section-12-10}&quot;">​</a></h2><p>每个方案使用同一基线比较，至少登记：方案描述、前瞻引用、规范前提、受影响者、权利底线、预期路径、最坏可接受结果、跨圈层溢出、成本与收益分布、信息价值、锁定风险、可逆性、资源成本、执行者、授权、停止、回滚和补救。</p><table tabindex="0"><thead><tr><th>比较维度</th><th>问题</th><th>不能用什么替代</th></tr></thead><tbody><tr><td>目标与路径</td><td>它试图改变哪条路径</td><td>抽象的“变好”</td></tr><tr><td>保护底板</td><td>谁可能受到不可接受损害</td><td>平均收益</td></tr><tr><td>分配</td><td>谁获益、谁付出、何时发生</td><td>总量净值</td></tr><tr><td>跨圈层溢出</td><td>局部改善是否外部化成本</td><td>主圈层指标</td></tr><tr><td>信息价值</td><td>是否能区分机制或路径</td><td>行动本身的戏剧性</td></tr><tr><td>可逆与锁定</td><td>错了能否停、退、补救</td><td>口头承诺</td></tr><tr><td>权限</td><td>谁可以决定、执行和申诉</td><td>模型建议或职位名称</td></tr><tr><td>不行动</td><td>不做会沿什么路径变化</td><td>假定零成本</td></tr></tbody></table><p>若方案之间无法用单一尺度比较，应保留多维结果和公开冲突，而不是强行求和。若价值前提之间冲突，应由有资格的主体和程序处理，模型应完整显示冲突位置与后果，可以在公开的规范前提下提出供审议的偏好与理由；不能替有资格的主体作具有约束力的最终决定。</p><p>信息价值可以写成一个受限的形式对象。对行动a、状态θ、信息Z及预先认可的效用U，EVSI=E_Z[max_a E(U|Z)]−max_a E(U)。免费获取且可以忽略Z、行动集合和目标不变时，EVSI不为负；现实调查还消耗时间、隐私和资源，并可能错过窗口或改变可选行动，因此应另计净价值。两条线索也可能只有联合取得才改变行动。知识本身的理解价值可以独立存在，不必全部折算为这一决策量。〔研究07.08；形式条件说明〕</p><h3 id="section-12-10-1" tabindex="-1">12.10.1　从可识别答案到可行选择 <a class="header-anchor" href="#section-12-10-1" aria-label="Permalink to &quot;12.10.1　从可识别答案到可行选择 {#section-12-10-1}&quot;">​</a></h3><p>问题可以有充分答案而行动仍不可行，行动也可以在尚未识别全部状态时具有共同可接受的选项。对与当前材料相容的每个状态 z，令 A_ok(z) 表示在已公开保护底线、资源与有效权限下可接受的动作。有限单轮确定性选择中，若交集 ∩ A_ok(z) 非空，就可在不先分辨全部状态的条件下比较其中的共同选项；这给出了保留未知而仍能有限行动的一种正面条件。若交集为空，“每种状态各有一种办法”便不足以说明当前能够选对，应检查补证、等待、缩小任务或另有依据的保护动作是否能改变条件。</p><p>这个交集只针对已列的可信状态和明确约束，不保证未知状态永远不出现。风险概率、成本或规范容忍度可以支持其他选择规则，但必须显式说明，不能把最坏情形准则暗藏为唯一理性。合法的随机或序贯策略也要按相应目标另行分析；上述单轮条件不将它们一并排除。</p><h3 id="section-12-10-2" tabindex="-1">12.10.2　多项方案的联合可行性 <a class="header-anchor" href="#section-12-10-2" aria-label="Permalink to &quot;12.10.2　多项方案的联合可行性 {#section-12-10-2}&quot;">​</a></h3><p>多个动作分别可行，还要检查它们同时实施时是否共享同一份容量、预算、工作人员和停止通道。两个单位服务都须在本期完成、而本期只有一个单位容量时，二者单独可行、联合不可行；下期新增容量不能补回本期已经错过的期限。增加同期容量或在有依据且获准的情况下调整期限，可以形成新的可行方案，但不得据此改写旧任务已经完成。</p><p>联合比较因此应把资源占用、任务依赖和关键截止连起来核算，防止各部门重复承诺同一资源。并行只在条件允许时缩短等待；存在串行依赖的查明、授权、实施与起效仍需接续。把首个节点完成当作最后受影响者已获保护，会同时误判时间和覆盖。</p><h2 id="section-12-11" tabindex="-1">12.11　行动上限与信息性试验 <a class="header-anchor" href="#section-12-11" aria-label="Permalink to &quot;12.11　行动上限与信息性试验 {#section-12-11}&quot;">​</a></h2><p>证据、可逆性、权限和保护共同决定行动上限。证据弱、风险高、不可逆或权限不足时，合适输出可能是先观察、缩小动作、改善信息、保护受影响者、启动申诉或当前不行动。</p><p>信息性试验不是免责任的“小动作”。它仍需说明试验对象、受影响者、最小范围、可逆性、停止、数据用途和补救。不能把低权力位置当作模型校准材料，也不能在没有真实退出能力时宣称自愿参与。</p><table tabindex="0"><thead><tr><th>条件组合</th><th>允许上限示例</th></tr></thead><tbody><tr><td>证据弱、损害低、可逆、授权清楚</td><td>小范围观察或试探行动</td></tr><tr><td>证据中等、损害可控、可回滚</td><td>分阶段行动并设强停止门</td></tr><tr><td>证据强但权限不足</td><td>提交有权限主体，不自行执行</td></tr><tr><td>证据强但不可逆且保护未满足</td><td>暂停，补足程序与保护</td></tr><tr><td>紧急安全威胁</td><td>仅按外部紧急授权做最小保护动作，并尽快复核</td></tr></tbody></table><h2 id="section-12-12" tabindex="-1">12.12　结果回写与模型学习 <a class="header-anchor" href="#section-12-12" aria-label="Permalink to &quot;12.12　结果回写与模型学习 {#section-12-12}&quot;">​</a></h2><p>前瞻和选择的结果回写只能追加。记录包括结果观察时间、来源、实际结果、路径匹配、校准指标、简单基线比较、意外效应、受影响位置复核、模型更新、断言降级、退役变量或路径和下一次复核。</p><p>行动结果不能只按主目标评价。还要检查副作用、跨圈层溢出、成本分配、申诉、无法退出者和长期时钟。一次成功不证明机制普遍成立，一次失败也可能来自执行偏离；两者要通过冻结合同区分，不能用执行解释随意救援模型。</p><h2 id="section-12-13" tabindex="-1">12.13　一个完整的前瞻—选择示例 <a class="header-anchor" href="#section-12-13" aria-label="Permalink to &quot;12.13　一个完整的前瞻—选择示例 {#section-12-13}&quot;">​</a></h2><p>继续公开离职事件。条件前瞻可以把目标设为“未来三个月团队自愿离职是否明显高于历史与同类团队基线”，输入截止为公开说明后一周。简单基线使用历史离职率和工时趋势；多圈层模型增加团队信任、管理回应、职业社群桥接、家庭照护与平台曝光。路径包括舆论消退而内部持续、制度调整并逐步修复、外部桥接触发连续退出等。</p><p>早期信号包括工时实际变化、申诉处理、成员表达、招聘与外部机会；反向信号包括政策发布但执行缺失、公开安静而内部沉默增加。三个月后比较多圈层模型与简单基线，不能只挑中间某个命中信号宣布成功。</p><p>有限选择至少比较：维持现状；只做公关回应；立即资源调整；先做可逆的工时与申诉试点；延迟重大重组以收集信息；允许团队成员转移；当前不做结构行动但加强保护与观察。每项都要检查权限、无法退出者、成本分配、跨圈层声誉与家庭影响、停止和补救。模型可以显示哪些方案在哪些条件下更可能改变路径，但最终选择仍取决于规范前提、合法授权和受影响者程序。在这些条件下，模型也应明确当前分析推荐、落选理由、代价及改判条件；推荐不改变尚未取得的执行权限。</p><h2 id="section-12-14" tabindex="-1">12.14　何时选择不做 <a class="header-anchor" href="#section-12-14" aria-label="Permalink to &quot;12.14　何时选择不做 {#section-12-14}&quot;">​</a></h2><p>不做可能是谨慎，也可能是逃避。以下情形支持当前不行动或只做保护性观察：对象与事实尚不清楚；行动不可逆而证据不足；权限缺失；保护底板未满足；预计行动会把成本转嫁给无法退出者；简单基线与复杂模型均无法区分路径；现有恢复过程可能被外部干预打断。</p><p>以下情形使不行动必须接受更严格审查：持续伤害正在发生；不作为强化既得优势；负责主体有明确法定义务或承诺；低权力位置无法自行退出；延迟会造成不可逆锁定；以“等待更多证据”为由无限推迟。此时即使不采取主行动，也可能需要最小保护、信息公开、申诉通道或临时承接。</p><h2 id="section-12-15" tabindex="-1">12.15　本部分的停止位置 <a class="header-anchor" href="#section-12-15" aria-label="Permalink to &quot;12.15　本部分的停止位置 {#section-12-15}&quot;">​</a></h2><p>条件前瞻层可以发布有目标、有期限、有基线、有信号、有校准和有回写的判断。有限选择层可以在规范、保护与授权都明确时比较行动、延迟、试探、退出和不行动，并给出条件化、可撤回的选择记录。尚未取得执行授权时，仍可在证据与明示规范前提允许的范围内完成分析推荐，完整说明选项、反方、分配后果和改判条件；其现实采用状态须另行登记。</p><p>它们不能保证未来，不能消除价值冲突，不能替代法律、专业规范、受影响者参与和现实授权，也不能把模型准确率兑换成统治资格。任何越过这些边界的调用都应由第十三部分的工具闸阻止，并由第十六部分治理、暂停或退役。</p><h2 id="section-12-16" tabindex="-1">12.16　面向读者的发布格式 <a class="header-anchor" href="#section-12-16" aria-label="Permalink to &quot;12.16　面向读者的发布格式 {#section-12-16}&quot;">​</a></h2><p>对外发布时，默认交付完整分析，开头直接给出当前判断及范围，随后完整展开条件、证据与不确定性。正文应按本次输出类型保留适用字段，包括当前截止时点、目标与期限、对象和圈层范围、简单基线、全部已经开展的实质路径比较、每条路径成立条件、早期与反向信号、表达强度、暂停和下一次复核。不得以不改变主结论、属于次要分支或不是决定性理由为由删去实质分析；不得把条件藏在脚注，或用“模型认为”替代证据责任。只有用户明确要求简答或规定较短篇幅时才压缩可见答案，并继续保存完整分析。超出单次容量时按章节连续交付并提供完整文件，说明尚未交付范围；摘要、附件链接与覆盖标记不能替代正文论证。</p><p>有限选择的分析应明确已经进入规范层，完整列出价值前提、决定主体、受影响位置、保护底板、可选方案、行动与不行动的分配后果、授权状态、行动上限、停止、回滚和补救。可以先给出当前分析推荐，再完整说明接受与排除各方案的理由、代价、反对意见及改判条件。若授权尚未通过，明确推荐供审议、现实执行尚未获准，不能用祈使语气伪装成可执行决定，也不能因没有执行权限而把已有依据的分析取舍退回问题清单。</p><table tabindex="0"><thead><tr><th>发布状态</th><th>可使用的表述</th><th>必须避免</th></tr></thead><tbody><tr><td>仅解释</td><td>“现有证据支持机制 A，并保留 B”</td><td>“因此下一步必然发生”</td></tr><tr><td>仅推演</td><td>“若 X 持续且 Y 发生，路径 P 获得支持”</td><td>“模型预测 P 已经确定”</td></tr><tr><td>已登记前瞻</td><td>“在期限 T 内，P 当前优先于 Q，见反向信号 S”</td><td>隐去基线、期限和失败条件</td></tr><tr><td>规范尚未通过</td><td>“可在明示前提下分析推荐；若要现实执行，仍需 N、PF、J 与 O”</td><td>“尚未取得授权但已可立即执行”</td></tr><tr><td>已获外部授权</td><td>“授权记录允许主体在上限内执行并按条件停止”</td><td>把授权归因于模型</td></tr></tbody></table><p>发布后的解释权也受治理。读者误把条件前瞻当确定预言、把人格候选当事实或把方案比较当命令时，发布者应更正，而不是利用误读扩大影响。任何更新都以新版本追加，原标题、概率、期限与失败记录保持可追踪。</p></div>',1)])])}const u=d(o,[["render",h]]);export{b as __pageData,u as default};
